1	package server
2	
3	import (
4		"encoding/json"
5		"io"
6		"mime"
7		"net/http"
8		"sort"
9		"strings"
10	)
11	
12	const (
13		notificationRoutesPath   = "/api/v1/notification-routes"
14		notificationRoutesPrefix = notificationRoutesPath + "/"
15		notificationPlanPath     = "/api/v1/notification-plan"
16	)
17	
18	// notificationRoute is an immutable routing document. It maps a set of alert
19	// rule ids to a receiver with a priority used when several routes cover the
20	// same alert. Replacements swap the pointer atomically, so readers never
21	// observe a half-updated route.
22	type notificationRoute struct {
23		id       string
24		ruleIDs  []string
25		receiver string
26		priority int
27	
28		// comment is a nullable string: nil echoes back as JSON null.
29		comment *string
30	}
31	
32	// ---- JSON wire shapes ------------------------------------------------------
33	
34	type notificationRouteJSON struct {
35		ID       string   `json:"id"`
36		RuleIDs  []string `json:"rule_ids"`
37		Receiver string   `json:"receiver"`
38		Priority int      `json:"priority"`
39		Comment  *string  `json:"comment"`
40	}
41	
42	func notificationRouteWireJSON(r *notificationRoute) notificationRouteJSON {
43		return notificationRouteJSON{
44			ID:       r.id,
45			RuleIDs:  append([]string(nil), r.ruleIDs...),
46			Receiver: r.receiver,
47			Priority: r.priority,
48			Comment:  r.comment,
49		}
50	}
51	
52	// ---- request decoding ------------------------------------------------------
53	
54	type rawNotificationRoute struct {
55		RuleIDs  *[]string       `json:"rule_ids"`
56		Receiver *string         `json:"receiver"`
57		Priority *int            `json:"priority"`
58		Comment  json.RawMessage `json:"comment"`
59	}
60	
61	// decodeNotificationRoute parses and fully validates a route body. It never
62	// returns a partially validated route.
63	func decodeNotificationRoute(body []byte) (*notificationRoute, bool) {
64		var raw rawNotificationRoute
65		if !strictDecode(body, &raw) {
66			return nil, false
67		}
68		if raw.RuleIDs == nil || raw.Receiver == nil || raw.Priority == nil || raw.Comment == nil {
69			return nil, false
70		}
71	
72		// rule_ids may reference rules that do not exist yet; the ids themselves
73		// still must be non-empty, distinct, valid identifiers.
74		ruleIDs, ok := validateIDList(*raw.RuleIDs)
75		if !ok {
76			return nil, false
77		}
78		receiver := *raw.Receiver
79		if !identPattern.MatchString(receiver) {
80			return nil, false
81		}
82		priority := *raw.Priority
83		if priority < 0 || priority > 1000 {
84			return nil, false
85		}
86		// comment is a nullable string: an explicit null is accepted and echoes
87		// back as null, but any other JSON type is rejected. A missing field was
88		// already rejected above (raw.Comment == nil).
89		var comment *string
90		if err := json.Unmarshal(raw.Comment, &comment); err != nil {
91			return nil, false
92		}
93	
94		return &notificationRoute{
95			ruleIDs:  ruleIDs,
96			receiver: receiver,
97			priority: priority,
98			comment:  comment,
99		}, true
100	}
101	
102	// ---- store operations ------------------------------------------------------
103	
104	func (s *metricStore) putNotificationRoute(r *notificationRoute) bool {
105		s.mu.Lock()
106		defer s.mu.Unlock()
107		_, existed := s.notificationRoutes[r.id]
108		s.notificationRoutes[r.id] = r
109		return !existed
110	}
111	
112	func (s *metricStore) getNotificationRoute(id string) (*notificationRoute, bool) {
113		s.mu.RLock()
114		defer s.mu.RUnlock()
115		r, ok := s.notificationRoutes[id]
116		return r, ok
117	}
118	
119	func (s *metricStore) deleteNotificationRoute(id string) bool {
120		s.mu.Lock()
121		defer s.mu.Unlock()
122		if _, ok := s.notificationRoutes[id]; !ok {
123			return false
124		}
125		delete(s.notificationRoutes, id)
126		return true
127	}
128	
129	// snapshotNotificationRoutes returns all routes sorted by id. Route objects
130	// are immutable, so the pointers stay safe after the lock is released.
131	func (s *metricStore) snapshotNotificationRoutes() []*notificationRoute {
132		s.mu.RLock()
133		defer s.mu.RUnlock()
134		return s.snapshotNotificationRoutesLocked()
135	}
136	
137	func (s *metricStore) snapshotNotificationRoutesLocked() []*notificationRoute {
138		out := make([]*notificationRoute, 0, len(s.notificationRoutes))
139		for _, r := range s.notificationRoutes {
140			out = append(out, r)
141		}
142		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
143		return out
144	}
145	
146	// ---- HTTP handlers ---------------------------------------------------------
147	
148	func registerNotificationRouteHandlers(mux *http.ServeMux, store *metricStore) {
149		mux.HandleFunc(notificationRoutesPath, func(w http.ResponseWriter, r *http.Request) {
150			if r.Method != http.MethodGet {
151				w.Header().Set("Allow", http.MethodGet)
152				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
153				return
154			}
155			routes := store.snapshotNotificationRoutes()
156			body := make([]notificationRouteJSON, 0, len(routes))
157			for _, route := range routes {
158				body = append(body, notificationRouteWireJSON(route))
159			}
160			writeJSON(w, http.StatusOK, map[string]any{"routes": body})
161		})
162	
163		mux.HandleFunc(notificationRoutesPrefix, func(w http.ResponseWriter, r *http.Request) {
164			id := strings.TrimPrefix(r.URL.Path, notificationRoutesPrefix)
165			switch r.Method {
166			case http.MethodGet, http.MethodDelete:
167				// Reads and deletions can only address an existing, syntactically
168				// valid route id; anything else is simply not found.
169				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
170					writeAPIError(w, "notification_route_not_found", http.StatusNotFound)
171					return
172				}
173				if r.Method == http.MethodGet {
174					handleNotificationRouteGet(w, id, store)
175				} else {
176					handleNotificationRouteDelete(w, id, store)
177				}
178			case http.MethodPut:
179				// A structurally nested path is outside this resource subtree;
180				// an identifier-shaped but invalid id is a bad identifier.
181				if id == "" || strings.Contains(id, "/") {
182					writeAPIError(w, "notification_route_not_found", http.StatusNotFound)
183					return
184				}
185				if !identPattern.MatchString(id) {
186					writeAPIError(w, "invalid_notification_route", http.StatusBadRequest)
187					return
